schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/program-dependency-aging-chart-recipe.json",
  "title": "Program dependency aging chart",
  "type": "object",
  "required": ["program", "owner", "chart_date", "checkpoint_weekday", "tracker_query", "extracted_at", "age_bands", "bands_adopted_on", "edges", "action_table", "resolved_log", "sle"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "timestamp": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "link_id": {"type": "string", "pattern": "^[A-Z][A-Z0-9]+-[0-9]+$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "program": {"type": "string", "minLength": 2},
    "owner": {"$ref": "#/definitions/handle"},
    "chart_date": {"$ref": "#/definitions/date"},
    "checkpoint_weekday": {"type": "string", "enum": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]},
    "tracker_query": {"type": "string", "minLength": 10},
    "extracted_at": {"$ref": "#/definitions/timestamp"},
    "chart_image": {"type": "string", "minLength": 3},
    "age_bands": {
      "type": "array",
      "minItems": 3,
      "items": {
        "type": "object",
        "required": ["label", "min_days", "max_days"],
        "additionalProperties": false,
        "properties": {
          "label": {"type": "string", "minLength": 1},
          "min_days": {"type": "integer", "minimum": 0},
          "max_days": {"type": ["integer", "null"], "minimum": 1}
        }
      }
    },
    "bands_adopted_on": {"$ref": "#/definitions/date"},
    "edges": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["link_id", "producer_team", "consumer_team", "dependency_type", "opened_at", "needed_by", "blocked_task_count", "age_days", "band", "slack_days"],
        "additionalProperties": false,
        "properties": {
          "link_id": {"$ref": "#/definitions/link_id"},
          "producer_team": {"type": "string", "minLength": 2},
          "consumer_team": {"type": "string", "minLength": 2},
          "dependency_type": {"type": "string", "enum": ["api-contract", "shared-component", "data-feed", "infrastructure", "review-approval", "environment", "other"]},
          "opened_at": {"$ref": "#/definitions/date"},
          "needed_by": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]},
          "blocked_task_count": {"type": "integer", "minimum": 0},
          "age_days": {"type": "integer", "minimum": 0},
          "band": {"type": "string", "minLength": 1},
          "slack_days": {"type": ["integer", "null"]},
          "superseded_from": {"$ref": "#/definitions/link_id"},
          "action": {
            "type": "object",
            "required": ["owner", "due_date", "text"],
            "additionalProperties": false,
            "properties": {
              "owner": {"$ref": "#/definitions/handle"},
              "due_date": {"$ref": "#/definitions/date"},
              "text": {"type": "string", "minLength": 12, "pattern": "^(?![Ww]aiting (on|for))"}
            }
          },
          "rebaseline": {
            "type": "object",
            "required": ["decision", "decided_by", "decided_on"],
            "additionalProperties": false,
            "properties": {
              "decision": {"type": "string", "enum": ["move-milestone", "cut-scope", "swap-producer"]},
              "decided_by": {"$ref": "#/definitions/handle"},
              "decided_on": {"$ref": "#/definitions/date"},
              "note": {"type": "string"}
            }
          }
        }
      }
    },
    "action_table": {
      "type": "array",
      "items": {"$ref": "#/definitions/link_id"},
      "uniqueItems": true
    },
    "resolved_log": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["link_id", "opened_at", "resolved_on", "age_days", "outcome", "needed_by"],
        "additionalProperties": false,
        "properties": {
          "link_id": {"$ref": "#/definitions/link_id"},
          "opened_at": {"$ref": "#/definitions/date"},
          "resolved_on": {"$ref": "#/definitions/date"},
          "age_days": {"type": "integer", "minimum": 0},
          "outcome": {"type": "string", "enum": ["delivered", "not-needed"]},
          "needed_by": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]}
        },
        "if": {"properties": {"outcome": {"const": "not-needed"}}},
        "then": {"properties": {"needed_by": {"$ref": "#/definitions/date"}}}
      }
    },
    "sle": {
      "type": "object",
      "required": ["resolved_count_12w", "status"],
      "additionalProperties": false,
      "properties": {
        "resolved_count_12w": {"type": "integer", "minimum": 0},
        "status": {"type": "string", "enum": ["line", "insufficient-data"]},
        "p85_days": {"type": "integer", "minimum": 0}
      },
      "if": {"properties": {"status": {"const": "line"}}},
      "then": {"required": ["resolved_count_12w", "status", "p85_days"], "properties": {"resolved_count_12w": {"minimum": 10}}},
      "else": {"properties": {"resolved_count_12w": {"maximum": 9}}, "not": {"required": ["p85_days"]}}
    }
  }
}

